from pathlib import Path
p=Path('index.html')
s=p.read_text()
if '/* Zip/Fidget tuned v2 */' in s:
    raise SystemExit('already tuned')

css=r'''
/* Zip/Fidget tuned v2 */
#zipLinePage .zip-stage{display:grid;grid-template-columns:repeat(var(--zip-cols,5),1fr);grid-template-rows:repeat(var(--zip-rows,7),1fr);gap:0;padding:0;border:1.5px solid #d7e1f3;border-radius:22px;background:#fff;overflow:hidden;touch-action:none;user-select:none}
#zipLinePage .zip-stage svg{z-index:3;pointer-events:none}
#zipLinePage .zip-cell{position:relative;border-right:1px solid #e3e9f5;border-bottom:1px solid #e3e9f5;background:rgba(255,255,255,.82);display:grid;place-items:center;min-width:0;min-height:0;z-index:1;touch-action:none}
#zipLinePage .zip-cell:nth-child(var(--zip-cols)n){border-right:0}
#zipLinePage .zip-cell.used{background:#edf3ff}
#zipLinePage .zip-cell.current{background:#dfe9ff}
#zipLinePage .zip-cell.anchor{font-weight:750;color:#3568ee;font-size:clamp(15px,4vw,24px)}
#zipLinePage .zip-cell.anchor:after{content:'';position:absolute;width:min(46%,30px);aspect-ratio:1;border-radius:50%;border:1.5px solid #9fb6ef;background:#fff;z-index:-1}
#zipLinePage .zip-cell.anchor.used:after{background:#3568ee;border-color:#3568ee}
#zipLinePage .zip-cell.anchor.used{color:#fff}
#zipLinePage .zip-path{stroke:#5d83ee;stroke-width:8;opacity:.92}
#zipLinePage .zip-live{stroke:#9fb4ed;stroke-width:6}
#zipLinePage .zip-footer span{font-size:13px;line-height:1.3}
#zipLinePage .zip-footer button{border-radius:999px}
#fidgetPage .fidget-stage{background:radial-gradient(circle at center,#fff 0 25%,#f8faff 58%,#eef3ff 100%)}
#fidgetPage .fidget-caption{font-size:12px;font-weight:600;color:#7e8fae;letter-spacing:.02em}
#fidgetPage .fidget-stage:after{content:'flick it';position:absolute;left:50%;top:50%;transform:translate(-50%,calc(50% + min(30vw,170px)));font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:#b1bdd3;pointer-events:none}
'''
s=s.replace('\n</style>','\n'+css+'\n</style>',1)

