new=r'''// ZIP LINE — fill every box, anchors in order
let zipLevel=1,zipCols=5,zipRows=7,zipSolution=[],zipAnchors=new Map(),zipPathCells=[],zipDrag=null;
function zipBasePath(cols,rows){const a=[];for(let y=0;y<rows;y++){if(y%2===0)for(let x=0;x<cols;x++)a.push([x,y]);else for(let x=cols-1;x>=0;x--)a.push([x,y])}return a}
function zipTransform(path,cols,rows,mode){let out=path.map(([x,y])=>[x,y]),c=cols,r=rows;if(mode&1)out=out.map(([x,y])=>[c-1-x,y]);if(mode&2)out=out.map(([x,y])=>[x,r-1-y]);if(mode&4){out=out.map(([x,y])=>[y,x]);[c,r]=[r,c]}return{path:out,cols:c,rows:r}}
function makeZip(){const rng=mulberry32(8301+zipLevel*131);zipCols=zipLevel<4?5:6;zipRows=zipLevel<7?7:8;let base=zipBasePath(zipCols,zipRows),t=zipTransform(base,zipCols,zipRows,Math.floor(rng()*8));zipSolution=t.path;zipCols=t.cols;zipRows=t.rows;const total=zipSolution.length,anchors=Math.min(4+Math.floor(zipLevel/2),8),idx=[0];for(let i=1;i<anchors-1;i++)idx.push(Math.round(i*(total-1)/(anchors-1)));idx.push(total-1);zipAnchors=new Map(idx.map((v,i)=>[v,i+1]));zipPathCells=[];zipDrag=null}
function zipKey(x,y){return x+','+y}
function renderZip(){if(!zipSolution.length)makeZip();const stage=$('zipStage');stage.style.setProperty('--zip-cols',zipCols);stage.style.setProperty('--zip-rows',zipRows);stage.innerHTML='<svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline id="zipPath" class="zip-path" points=""></polyline><line id="zipLive" class="zip-live" x1="0" y1="0" x2="0" y2="0" hidden></line></svg>';const used=new Set(zipPathCells.map(([x,y])=>zipKey(x,y)));for(let y=0;y<zipRows;y++)for(let x=0;x<zipCols;x++){const solIndex=zipSolution.findIndex(p=>p[0]===x&&p[1]===y),anchor=zipAnchors.get(solIndex),d=document.createElement('div');d.className='zip-cell'+(used.has(zipKey(x,y))?' used':'')+(zipPathCells.length&&zipPathCells.at(-1)[0]===x&&zipPathCells.at(-1)[1]===y?' current':'')+(anchor?' anchor':'');d.dataset.x=x;d.dataset.y=y;if(anchor)d.textContent=anchor;stage.appendChild(d)}drawZipPath();$('zipLevel').textContent=zipLevel;const nextAnchor=[...zipAnchors.entries()].find(([idx,n])=>idx>=zipPathCells.length);$('zipMessage').textContent=zipPathCells.length===zipSolution.length?'Complete — every box used.':zipPathCells.length?'Keep filling every box · next number '+(nextAnchor?nextAnchor[1]:'✓'):'Start at 1 · use every box.'}
function drawZipPath(){const pts=zipPathCells.map(([x,y])=>((x+.5)/zipCols*100)+','+((y+.5)/zipRows*100)).join(' ');$('zipPath').setAttribute('points',pts)}
function zipExpectedAnchorAtCell(x,y){const si=zipSolution.findIndex(p=>p[0]===x&&p[1]===y);return zipAnchors.get(si)||0}
function zipNextAnchorNumber(){let passed=0;for(const [idx,n] of zipAnchors)if(idx<zipPathCells.length)passed=n;return passed+1}
function zipTryCell(x,y){if(!zipPathCells.length){const first=zipSolution[0];if(x!==first[0]||y!==first[1]){toast('Start at 1');return false}}else{const [px,py]=zipPathCells.at(-1),dx=Math.abs(x-px),dy=Math.abs(y-py);if(dx+dy!==1)return false;const prevIndex=zipPathCells.findIndex(p=>p[0]===x&&p[1]===y);if(prevIndex===zipPathCells.length-2){zipPathCells.pop();renderZip();return true}if(prevIndex>=0)return false;const anchor=zipExpectedAnchorAtCell(x,y),next=zipNextAnchorNumber();if(anchor&&anchor!==next){toast('Reach '+next+' first');return false}}zipPathCells.push([x,y]);beep(360+Math.min(300,zipPathCells.length*5),.025);renderZip();if(zipPathCells.length===zipSolution.length){const exact=zipPathCells.every((p,i)=>p[0]===zipSolution[i][0]&&p[1]===zipSolution[i][1]);if(exact){toast('Every box connected ✦');setTimeout(()=>{zipLevel++;makeZip();renderZip()},850)}else{toast('Almost — check the number order')}}return true}
const zipStage=$('zipStage');zipStage.addEventListener('pointerdown',e=>{const c=e.target.closest('.zip-cell');if(!c)return;e.preventDefault();zipDrag={id:e.pointerId};try{zipStage.setPointerCapture(e.pointerId)}catch{};zipTryCell(+c.dataset.x,+c.dataset.y)});zipStage.addEventListener('pointermove',e=>{if(!zipDrag||zipDrag.id!==e.pointerId)return;const c=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('.zip-cell');if(c)zipTryCell(+c.dataset.x,+c.dataset.y)});function endZip(){zipDrag=null;const l=$('zipLive');if(l)l.hidden=true}zipStage.addEventListener('pointerup',endZip);zipStage.addEventListener('pointercancel',endZip);$('zipReset').addEventListener('click',()=>{zipPathCells=[];renderZip()});

// FIDGET — high-response sensory spin
const FIDGET_COLORS={blue:'#4f78ec',green:'#3e9b70',amber:'#d8942f',pink:'#d970a9',graphite:'#596171'};let fidgetColor=storage.get('fidget.color','blue'),fidgetType=storage.get('fidget.type','tri'),fAngle=0,fVel=0,fW=0,fH=0,fDpr=1,fPointer=null,fLastT=0,fSplashes=[];const fc=$('fidgetCanvas'),fctx=fc.getContext('2d');if(!FIDGET_COLORS[fidgetColor])fidgetColor='blue';if(!['tri','bar','ring','gear'].includes(fidgetType))fidgetType='tri';
function resizeFidget(){const r=fc.parentElement.getBoundingClientRect();if(r.width<1||r.height<1)return;fW=r.width;fH=r.height;fDpr=Math.min(2,devicePixelRatio||1);fc.width=Math.round(fW*fDpr);fc.height=Math.round(fH*fDpr);fctx.setTransform(fDpr,0,0,fDpr,0,0);drawFidget()}
function fidgetMark(x,y,r,color,alpha=1){fctx.save();fctx.globalAlpha=alpha;fctx.beginPath();fctx.arc(x,y,r,0,Math.PI*2);fctx.fillStyle=color;fctx.fill();fctx.restore()}
function splashFidget(power=1){const c=FIDGET_COLORS[fidgetColor],cx=fW/2,cy=fH/2,n=Math.min(18,5+Math.floor(power*7));for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,sp=(35+Math.random()*95)*(1+power*.45);fSplashes.push({x:cx,y:cy,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,r:2+Math.random()*5,life:1,c})}fSplashes.push({ring:true,x:cx,y:cy,r:Math.min(fW,fH)*.12,life:1,c})}
function drawFidget(){if(!fW)return;const cx=fW/2,cy=fH/2,R=Math.min(fW,fH)*.28,c=FIDGET_COLORS[fidgetColor],speed=Math.abs(fVel);fctx.clearRect(0,0,fW,fH);if(speed>.8){const glow=Math.min(.18,speed/90);fctx.save();fctx.globalAlpha=glow;fctx.fillStyle=c;fctx.beginPath();fctx.arc(cx,cy,R*1.45,0,Math.PI*2);fctx.fill();fctx.restore()}for(const p of fSplashes){fctx.save();fctx.globalAlpha=Math.max(0,p.life)*(p.ring?.35:.8);if(p.ring){fctx.strokeStyle=p.c;fctx.lineWidth=3;fctx.beginPath();fctx.arc(p.x,p.y,p.r,0,Math.PI*2);fctx.stroke()}else fidgetMark(p.x,p.y,p.r,p.c,p.life);fctx.restore()}fctx.save();fctx.translate(cx,cy);fctx.rotate(fAngle);fctx.fillStyle=c;fctx.strokeStyle=c;fctx.lineWidth=Math.max(18,R*.2);fctx.lineCap='round';if(fidgetType==='tri'){for(let i=0;i<3;i++){const a=i*Math.PI*2/3,x=Math.cos(a)*R,y=Math.sin(a)*R;fctx.beginPath();fctx.moveTo(0,0);fctx.lineTo(x,y);fctx.stroke();fidgetMark(x,y,R*.26,c)}}else if(fidgetType==='bar'){fctx.beginPath();fctx.moveTo(-R,0);fctx.lineTo(R,0);fctx.stroke();fidgetMark(-R,0,R*.28,c);fidgetMark(R,0,R*.28,c)}else if(fidgetType==='ring'){fctx.lineWidth=R*.24;fctx.beginPath();fctx.arc(0,0,R*.78,0,Math.PI*2);fctx.stroke();for(let i=0;i<4;i++){const a=i*Math.PI/2;fidgetMark(Math.cos(a)*R*.78,Math.sin(a)*R*.78,R*.16,c)}}else{for(let i=0;i<10;i++){const a=i*Math.PI/5;fctx.save();fctx.rotate(a);fctx.fillRect(R*.52,-R*.12,R*.48,R*.24);fctx.restore()}fidgetMark(0,0,R*.64,c)}fidgetMark(0,0,R*.27,'#fff');fidgetMark(0,0,R*.14,c);fctx.restore();$('fidgetSpeed').textContent=Math.round(speed*14)}
function setFidgetColor(v){if(!FIDGET_COLORS[v])return;fidgetColor=v;storage.set('fidget.color',v);document.querySelectorAll('[data-fidget-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.fidgetColor===v)));splashFidget(.5);drawFidget()}function setFidgetType(v){if(!['tri','bar','ring','gear'].includes(v))return;fidgetType=v;storage.set('fidget.type',v);document.querySelectorAll('[data-fidget-type]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.fidgetType===v)));splashFidget(.65);drawFidget()}document.querySelectorAll('[data-fidget-color]').forEach(b=>b.addEventListener('click',()=>setFidgetColor(b.dataset.fidgetColor)));document.querySelectorAll('[data-fidget-type]').forEach(b=>b.addEventListener('click',()=>setFidgetType(b.dataset.fidgetType)));setFidgetColor(fidgetColor);setFidgetType(fidgetType);
function fAngleAt(x,y){const r=fc.getBoundingClientRect();return Math.atan2(y-(r.top+r.height/2),x-(r.left+r.width/2))}fc.addEventListener('pointerdown',e=>{e.preventDefault();const a=fAngleAt(e.clientX,e.clientY);fPointer={id:e.pointerId,a,t:performance.now(),x:e.clientX,y:e.clientY};fVel*=.35;try{fc.setPointerCapture(e.pointerId)}catch{};splashFidget(.35)});fc.addEventListener('pointermove',e=>{if(!fPointer||fPointer.id!==e.pointerId)return;const now=performance.now(),a=fAngleAt(e.clientX,e.clientY);let d=a-fPointer.a;if(d>Math.PI)d-=Math.PI*2;if(d<-Math.PI)d+=Math.PI*2;const dx=e.clientX-fPointer.x,dy=e.clientY-fPointer.y,travel=Math.hypot(dx,dy),gain=2.4;fAngle+=d*gain;const dt=Math.max(4,now-fPointer.t),angular=d/dt*1000*gain,linear=Math.min(10,travel/dt*18);fVel=clamp(angular+Math.sign(angular||d||1)*linear,-34,34);if(travel>9&&Math.random()<.38)splashFidget(Math.min(1.4,travel/28));fPointer.a=a;fPointer.t=now;fPointer.x=e.clientX;fPointer.y=e.clientY;drawFidget()});function releaseFidget(){if(fPointer&&Math.abs(fVel)>2.5)splashFidget(Math.min(2,Math.abs(fVel)/14));fPointer=null}fc.addEventListener('pointerup',releaseFidget);fc.addEventListener('pointercancel',releaseFidget);
function fidgetFrame(t){const dt=fLastT?Math.min(.05,(t-fLastT)/1000):0;fLastT=t;if(!fPointer&&Math.abs(fVel)>.001){fAngle+=fVel*dt;fVel*=Math.pow(.994,dt*60);if(Math.abs(fVel)<.001)fVel=0}for(const p of fSplashes){p.life-=dt*(p.ring?1.2:1.8);if(p.ring)p.r+=dt*120;else{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.965,dt*60);p.vy*=Math.pow(.965,dt*60);p.vy+=20*dt}}fSplashes=fSplashes.filter(p=>p.life>0);if(currentPage==='fidget'&&(Math.abs(fVel)>.001||fSplashes.length||fPointer))drawFidget();requestAnimationFrame(fidgetFrame)}requestAnimationFrame(fidgetFrame);
'''

